#[test]
fn the_uncompressed_cap_is_exact_and_holds_for_a_real_bomb() {
    let dir = Dir::new();
    // 4 MiB of zeros deflate to a few KiB.
    let zeros = vec![0u8; 4 * 1024 * 1024];
    let path = dir.zip(&[
        ("basic/basic.php", MAIN_PHP.as_bytes()),
        ("basic/zeros", &zeros),
    ]);
    assert!(std::fs::metadata(&path).unwrap().len() < 64 * 1024);
    let total = (MAIN_PHP.len() + zeros.len()) as u64;
    let limits = |uncompressed_bytes| Limits {
        uncompressed_bytes,
        ..Limits::PLAN
    };
    assert!(matches!(
        refused_with(&path, limits(total - 1)),
        PackageDefect::TooLargeUncompressed { .. }
    ));
    let package = PluginPackage::inspect_with(&path, &hints(), limits(total)).unwrap();
    assert_eq!(package.uncompressed_size(), total);
}

#[test]
fn entries_sharing_their_data_exhaust_the_read_budget() {
    // The overlapping-entries bomb: 200 directory records point at one
    // 64 KiB stored entry, so a reader would go through it 200 times.
    let dir = Dir::new();
    let data = vec![b'x'; 64 * 1024];
    let mut entries = vec![Raw::file("basic/f0.txt", &data)];
    entries.extend((1..200).map(|index| Raw {
        shares: Some(0),
        ..Raw::file(&format!("basic/f{index}.txt"), &data)
    }));
    let path = dir.write("plugin.zip", &raw_zip(&entries));
    let size = std::fs::metadata(&path).unwrap().len();
    assert!(matches!(
        refused(&path),
        PackageDefect::ExcessiveReads { max } if max == archive::read_budget(size)
    ));
}

#[test]
fn fake_end_records_exhaust_the_read_budget_quickly() {
    // Each end-of-directory record claims one entry at offset 0, and none is
    // there, so the reader would scan the whole file once per record.
    let dir = Dir::new();
    let mut bytes = vec![0u8; 2 * 1024 * 1024];
    let mut record = 0x0605_4b50u32.to_le_bytes().to_vec();
    for field in [0u16, 0, 1, 1] {
        record.extend_from_slice(&field.to_le_bytes());
    }
    for field in [46u32, 0] {
        record.extend_from_slice(&field.to_le_bytes());
    }
    record.extend_from_slice(&0u16.to_le_bytes());
    for _ in 0..20_000 {
        bytes.extend_from_slice(&record);
    }
    let path = dir.write("plugin.zip", &bytes);
    let started = std::time::Instant::now();
    // Inspection refuses the file before the zip crate sees it: it has more
    // than one end record.
    assert!(matches!(refused(&path), PackageDefect::Ambiguous { .. }));
    // The read budget still stops the zip crate's own search, should
    // anything reach it.
    let budget = archive::read_budget(bytes.len() as u64);
    let reader = archive::Budgeted::new(bytes, budget);
    let left = reader.left();
    assert!(zip::ZipArchive::new(reader).is_err());
    assert_eq!(left.get(), 0, "the budget is spent");
    assert!(started.elapsed() < std::time::Duration::from_secs(20));
}

#[test]
fn honest_zips_read_far_less_than_the_budget() {
    // Many small entries (header-heavy) and a large compressible one.
    let names: Vec<String> = (0..2000)
        .map(|index| format!("basic/inc/f{index}.php"))
        .collect();
    let mut files: Vec<(&str, &[u8])> = vec![("basic/basic.php", MAIN_PHP.as_bytes())];
    files.extend(names.iter().map(|name| (name.as_str(), &b"<?php\n"[..])));
    let big = b"lorem ipsum dolor sit amet ".repeat(40_000);
    files.push(("basic/big.txt", &big));
    for bytes in [
        zip_bytes(&files),
        raw_zip(&raw_files(&files)),
        zip_bytes(&[("basic/basic.php", MAIN_PHP.as_bytes())]),
    ] {
        let size = bytes.len() as u64;
        let mut archive = archive::Archive::open(bytes, Limits::PLAN).unwrap();
        let entries = archive.entries().unwrap();
        for entry in entries.iter().filter(|entry| !entry.is_dir) {
            let mut probe = archive::Probe::new(HEADER_BYTES, Vec::new());
            archive.verify(entry, &mut probe).unwrap();
        }
        // About twice the size; the budget allows four times plus 1 MiB.
        assert!(
            archive.bytes_read() <= 2 * size + 64 * 1024,
            "read {} of a {size}-byte zip",
            archive.bytes_read()
        );
    }
}

#[test]
fn the_plan_limits_are_the_documented_ones() {
    assert_eq!(MAX_PACKAGE_BYTES, 256 * 1024 * 1024);
    assert_eq!(MAX_ENTRIES, 100_000);
    assert_eq!(MAX_UNCOMPRESSED_BYTES, 1 << 30);
    assert_eq!(HEADER_BYTES, 8192);
    assert_eq!(
        Limits::PLAN,
        Limits {
            file_bytes: MAX_PACKAGE_BYTES,
            entries: MAX_ENTRIES,
            uncompressed_bytes: MAX_UNCOMPRESSED_BYTES,
        }
    );
}

// ── Plugin rule and headers ────────────────────────────────────────────────

#[test]
fn a_missing_plugin_name_is_refused() {
    let dir = Dir::new();
    let path = dir.zip(&[
        ("basic/basic.php", b"<?php\n/* Version: 1.0 */\n"),
        ("basic/inc/deep.php", MAIN_PHP.as_bytes()),
        ("basic/.hidden.php", MAIN_PHP.as_bytes()),
        ("basic/readme.txt", MAIN_PHP.as_bytes()),
    ]);
    let error = inspect(&path).unwrap_err();
    assert_eq!(error.code(), Code::PackageInvalid);
    assert!(matches!(
        &error,
        Error::PackageInvalid { defect: PackageDefect::NoPluginFile { slug }, .. } if slug == "basic"
    ));
    assert!(
        error.to_string().ends_with(
            "has no PHP file directly in 'basic' with a 'Plugin Name' header in its first 8 KiB"
        ),
        "{error}"
    );
}

#[test]
fn several_headered_files_give_a_warning() {
    let dir = Dir::new();
    let path = dir.zip(&[
        ("basic/zz.php", b"<?php /* Plugin Name: Second plugin */"),
        ("basic/basic.php", MAIN_PHP.as_bytes()),
        ("basic/aa.php", b"<?php /* Plugin Name: Third plugin */"),
    ]);
    let package = accepted(&path);
    assert_eq!(package.main_file(), "basic/basic.php");
    let expected = PackageWarning::SeveralPluginFiles {
        main: "basic/basic.php".into(),
        others: vec!["basic/aa.php".into(), "basic/zz.php".into()],
    };
    assert_eq!(package.warnings(), [expected]);
    assert_eq!(
        package.warnings()[0].to_string(),
        "several PHP files have a 'Plugin Name' header: 'basic/basic.php' is used as the main \
         file, and WordPress also lists 'basic/aa.php', 'basic/zz.php' as separate plugin(s)"
    );
}

#[test]
fn without_slug_php_the_first_headered_file_is_main() {
    let dir = Dir::new();
    let path = dir.zip(&[
        ("basic/zeta.php", b"<?php /* Plugin Name: Zeta */"),
        ("basic/alpha.php", b"<?php /* Plugin Name: Alpha */"),
        ("basic/basic.php", b"<?php // no header"),
    ]);
    let package = accepted(&path);
    assert_eq!(package.main_file(), "basic/alpha.php");
    assert_eq!(package.headers().name, "Alpha");
}

#[test]
fn headers_beyond_8_kib_are_ignored() {
    let dir = Dir::new();
    let mut late = b"<?php\n".to_vec();
    late.extend(std::iter::repeat_n(b'/', HEADER_BYTES));
    late.extend_from_slice(b"\n/* Plugin Name: Too late */\n");
    let path = dir.zip(&[("basic/basic.php", &late)]);
    assert!(matches!(refused(&path), PackageDefect::NoPluginFile { .. }));
}

#[test]
fn crlf_headers_are_read() {
    let dir = Dir::new();
    let path = dir.zip(&[(
        "basic/basic.php",
        b"<?php\r\n/**\r\n * Plugin Name: Windows\r\n * Version: 4.0\r\n */\r\n",
    )]);
    let package = accepted(&path);
    assert_eq!(package.headers().name, "Windows");
    assert_eq!(package.headers().version.as_deref(), Some("4.0"));
}

#[test]
fn a_multibyte_character_at_the_8_kib_boundary_does_not_panic() {
    let dir = Dir::new();
    let line = "Plugin Name: \u{65e5}\u{672c}";
    // Start the second three-byte character at byte 8191.
    let filler = "\n".repeat(HEADER_BYTES - (line.len() - 2));
    let text = format!("{filler}{line} and more");
    let path = dir.zip(&[("basic/basic.php", text.as_bytes())]);
    assert_eq!(accepted(&path).headers().name, "\u{65e5}\u{fffd}");
}

// ── Variants ───────────────────────────────────────────────────────────────

#[test]
fn backwpup_pro_variants_are_told_apart_by_their_marker() {
    let dir = Dir::new();
    for (needle, variant) in [
        ("https://backwpup.de/", "pro-de"),
        ("https://backwpup.com/", "pro-en"),
    ] {
        let license = format!(
            "<?php\nnamespace Inpsyde\\BackWPup\\Pro\\License;\nclass License {{\n\
             \tconst WC_API_URL = '{needle}';\n}}\n"
        );
        let package = accepted(&backwpup_pro(&dir, license.as_bytes()));
        assert_eq!(package.slug(), "backwpup-pro");
        assert_eq!(package.main_file(), "backwpup-pro/backwpup.php");
        assert_eq!(package.headers().name, "BackWPup Pro");
        assert!(package.headers().network);
        assert_eq!(
            package.variant(),
            &VariantDetection::Detected(variant.into())
        );
        assert!(package.warnings().is_empty());
    }
}

#[test]
fn a_pro_zip_without_a_known_marker_is_undetermined() {
    let dir = Dir::new();
    let package = accepted(&backwpup_pro(
        &dir,
        b"<?php const WC_API_URL = 'https://example.org/';",
    ));
    assert_eq!(package.variant(), &VariantDetection::Undetermined);
    // No marker file at all.
    let path = dir.zip(&[(
        "backwpup-pro/backwpup.php",
        b"<?php /* Plugin Name: BackWPup Pro */",
    )]);
    assert_eq!(accepted(&path).variant(), &VariantDetection::Undetermined);
    // A marker path that is a folder is no marker.
    let marker = format!("backwpup-pro/{LICENSE}/");
    let path = dir.zip(&[
        (
            "backwpup-pro/backwpup.php",
            b"<?php /* Plugin Name: BackWPup Pro */",
        ),
        (&marker, b""),
    ]);
    assert_eq!(accepted(&path).variant(), &VariantDetection::Undetermined);
}

#[test]
fn both_markers_matching_is_ambiguous() {
    let dir = Dir::new();
    let package = accepted(&backwpup_pro(
        &dir,
        b"https://backwpup.de/ and https://backwpup.com/",
    ));
    assert_eq!(package.variant(), &VariantDetection::Undetermined);
    assert_eq!(
        package.warnings(),
        [PackageWarning::AmbiguousVariant {
            variants: vec!["pro-de".into(), "pro-en".into()],
        }]
    );
    assert_eq!(
        package.warnings()[0].to_string(),
        "the markers of several variants match ('pro-de', 'pro-en'), so the variant is \
         undetermined"
    );
}

#[test]
fn a_marker_split_across_read_chunks_is_found() {
    let dir = Dir::new();
    // Put the needle across the 64 KiB decompression chunk boundary, deep
    // inside a large file.
    let mut license = vec![b'x'; 64 * 1024 - 7];
    license.extend_from_slice(b"https://backwpup.com/");
    license.extend(std::iter::repeat_n(b'y', 200 * 1024));
    let package = accepted(&backwpup_pro(&dir, &license));
    assert_eq!(
        package.variant(),
        &VariantDetection::Detected("pro-en".into())
    );
}

#[test]
fn markers_are_only_looked_for_in_their_own_file() {
    let dir = Dir::new();
    let path = dir.zip(&[
        (
            "backwpup-pro/backwpup.php",
            b"<?php /* Plugin Name: BackWPup Pro */ // https://backwpup.de/",
        ),
        ("backwpup-pro/inc/Other.php", b"https://backwpup.de/"),
    ]);
    assert_eq!(accepted(&path).variant(), &VariantDetection::Undetermined);
}

#[test]
fn single_variant_and_unknown_slugs() {
    let dir = Dir::new();
    let free = dir.zip(&[(
        "backwpup/backwpup.php",
        b"<?php /* Plugin Name: BackWPup */",
    )]);
    assert_eq!(
        accepted(&free).variant(),
        &VariantDetection::Detected("free".into())
    );
    let rocket = dir.zip(&[(
        "wp-rocket/wp-rocket.php",
        b"<?php /* Plugin Name: WP Rocket */",
    )]);
    assert_eq!(
        accepted(&rocket).variant(),
        &VariantDetection::NotApplicable
    );
    let other = dir.zip(&[("akismet/akismet.php", b"<?php /* Plugin Name: Akismet */")]);
    assert_eq!(accepted(&other).variant(), &VariantDetection::NotApplicable);
    // Without hints, nothing is known.
    let package = PluginPackage::inspect(&free, &PluginHints::default()).unwrap();
    assert_eq!(package.variant(), &VariantDetection::NotApplicable);
}

// ── Errors ─────────────────────────────────────────────────────────────────

#[test]
fn errors_name_the_file_and_the_rule() {
    let dir = Dir::new();
    let path = dir.zip(&[("one/one.php", MAIN_PHP.as_bytes()), ("two/two.php", b"")]);
    let error = inspect(&path).unwrap_err();
    assert_eq!(error.code(), Code::PackageInvalid);
    assert_eq!(Code::PackageInvalid.as_str(), "package_invalid");
    assert!(error.problems().is_empty());
    assert_eq!(
        error.to_string(),
        format!(
            "invalid plugin package '{}': has 2 top-level folders ('one', 'two'); a plugin \
             zip holds exactly one",
            path.display()
        )
    );
    // The defect is the error's source.
    let source = std::error::Error::source(&error).map(ToString::to_string);
    assert_eq!(
        source.as_deref(),
        Some("has 2 top-level folders ('one', 'two'); a plugin zip holds exactly one")
    );
}

#[test]
fn hostile_names_are_escaped_in_messages() {
    let dir = Dir::new();
    let entries = raw_files(&[
        ("basic/basic.php", MAIN_PHP.as_bytes()),
        ("\u{1b}[2J'x", b""),
    ]);
    let path = dir.write("plugin.zip", &raw_zip(&entries));
    let message = inspect(&path).unwrap_err().to_string();
    assert!(message.contains("'\\u{1b}[2J\\'x'"), "{message}");
    assert!(!message.contains('\u{1b}'), "{message}");
}

#[test]
fn long_name_lists_are_summarized() {
    let names: Vec<String> = (0..8).map(|index| format!("r{index}")).collect();
    assert_eq!(list(&names), "'r0', 'r1', 'r2', 'r3', 'r4', and 3 more");
    assert_eq!(list(&names[..2]), "'r0', 'r1'");
}

#[test]
fn every_defect_has_a_message() {
    let defects = [
        PackageDefect::Io(std::io::Error::other("boom")),
        PackageDefect::NotAFile,
        PackageDefect::NotZipName,
        PackageDefect::TooLarge { max: 1 },
        PackageDefect::NotZip("bad".into()),
        PackageDefect::TooManyEntries { count: 2, max: 1 },
        PackageDefect::ExcessiveReads { max: 1 },
        PackageDefect::TooLargeUncompressed { max: 1 },
        PackageDefect::UnsafePath {
            entry: "a".into(),
            reason: "is bad",
        },
        PackageDefect::Encrypted { entry: "a".into() },
        PackageDefect::UnsupportedCompression {
            entry: "a".into(),
            method: "Bzip2".into(),
        },
        PackageDefect::CorruptEntry {
            entry: "a".into(),
            detail: "bad".into(),
        },
        PackageDefect::Empty,
        PackageDefect::FileAtRoot { entry: "a".into() },
        PackageDefect::SeveralRoots {
            roots: vec!["a".into(), "b".into()],
        },
        PackageDefect::InvalidSlug {
            slug: "-a".into(),
            reason: "bad".into(),
        },
        PackageDefect::NoPluginFile { slug: "a".into() },
        PackageDefect::Ambiguous {
            detail: "two end records".into(),
        },
        PackageDefect::DuplicateEntry { entry: "a".into() },
    ];
    for defect in defects {
        assert!(!defect.to_string().is_empty(), "{defect:?}");
    }
}
